/* ===================== BÀI 13 · Truyền dữ liệu và thao tác bit ===================== */
/* Bài 13 · Truyền dữ liệu và thao tác bit (AMTS-EMB-001-M04-L01, MC51-013) — sinh bởi tools/author/mcu8051/l13.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR13=[{"label":"Ví dụ: Các kiểu MOV và mã máy","code":"; Ví dụ 1: các kiểu MOV, mã máy và số chu kỳ\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#3CH                  ; A = 3CH (số tức thời)\n        MOV     R0,#40H                 ; R0 = 40H: dùng làm con trỏ\n        MOV     @R0,A                   ; ô 40H = A (gián tiếp)\n        MOV     31H,@R0                 ; ô 31H = ô 40H\n        MOV     32H,31H                 ; ô 32H = ô 31H (trực tiếp)\n        MOV     R2,32H                  ; R2 = ô 32H\n        MOV     DPTR,#1234H             ; DPH = 12H, DPL = 34H\n        SJMP    $\n        END\n","note":"Bấm Từng bước và đọc cột byte, chu kỳ: lệnh qua A tốn 1 chu kỳ, lệnh giữa hai ô nhớ (MOV 31H,@R0, MOV 32H,31H, MOV R2,32H) tốn 2. Mã của MOV 32H,31H là 85 31 32: nguồn trước, đích sau. Đoán trước: sau 7 lệnh, ô 32H và R2 bằng bao nhiêu? (đều 3CH; tổng 11 chu kỳ tới SJMP $).","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Trao đổi bằng XCH và XCHD","code":"; Ví dụ 2: trao đổi dữ liệu bằng XCH và XCHD\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#12H                  ; A = 12H\n        MOV     R1,#30H                 ; R1 trỏ tới ô 30H\n        MOV     30H,#0ABH               ; ô 30H = ABH\n        XCH     A,30H                   ; đổi chỗ A và ô 30H\n        XCHD    A,@R1                   ; đổi 4 bit thấp của A và ô 30H\n        XCH     A,R1                    ; đổi chỗ A và R1\n        SJMP    $\n        END\n","note":"XCH A,30H đổi cả byte: A = ABH, ô 30H = 12H. XCHD A,@R1 chỉ đổi 4 bit thấp: A = A2H, ô 30H = 1BH. XCH A,R1 (mã C9, 1 byte): A = 30H, R1 = A2H. Cả ba lệnh trao đổi chỉ tốn 1 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: SETB, CLR, CPL từng chân LED","code":"; Ví dụ 3: SETB, CLR, CPL từng chân LED\n; Chip: AT89S52, thạch anh 12 MHz.\n; Nối dây (giả định): LED sáng khi chân cổng = 0.\n        ORG     0000H\n        CLR     P1.0                    ; P1.0 = 0: LED 0 sáng\n        CLR     P1.3                    ; LED 3 sáng\n        CPL     P1.0                    ; đảo P1.0: LED 0 tắt\n        SETB    P1.3                    ; P1.3 = 1: LED 3 tắt\n        CPL     P1.7                    ; đảo P1.7: LED 7 sáng\n        SJMP    $\n        END\n","note":"Mỗi lệnh bit 2 byte, 1 chu kỳ, chỉ đổi đúng một chân: LED 0 sáng rồi tắt, LED 3 sáng rồi tắt, cuối cùng chỉ LED 7 sáng. Đoán trước: P1 cuối bằng bao nhiêu? (7FH).","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bit trong vùng 20H–2FH và cờ C","code":"; Ví dụ 4: bit trong vùng 20H-2FH và cờ C\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     24H,#00H                ; byte 24H chứa bit 20H..27H\n        SETB    20H                     ; bit 20H = bit 0 của byte 24H\n        SETB    27H                     ; bit 27H = bit 7 của byte 24H\n        MOV     A,24H                   ; A = 81H\n        MOV     C,ACC.0                 ; C = bit 0 của A\n        CPL     C                       ; đảo C\n        MOV     P1.1,C                  ; ghi C ra chân P1.1\n        SJMP    $\n        END\n","note":"SETB 20H và SETB 27H là lệnh bit: bit 20H, 27H nằm trong byte 24H, nên byte 24H thành 81H (xem phần Bộ nhớ). MOV C,ACC.0 lấy bit 0 của A; sau CPL C, C = 0 và MOV P1.1,C (2 chu kỳ) làm LED P1.1 sáng: P1 = FDH.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: CLR 30H xóa bit, không xóa byte","code":"; Ví dụ 5 (bẫy): CLR 30H xóa một BIT, không xóa byte 30H\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     30H,#0FFH               ; byte 30H = FFH\n        MOV     26H,#0FFH               ; byte 26H = FFH\n        CLR     30H                     ; muốn xóa byte 30H?\n        MOV     A,30H                   ; đọc lại byte 30H\n        MOV     B,26H                   ; đọc lại byte 26H\n        SJMP    $\n        END\n","note":"CLR 30H là lệnh bit (mã C2 30), nên xóa bit 30H = bit 0 của byte 26H. Kết quả A = FFH (byte 30H không đổi), B = FEH (byte 26H mất bit 0). Muốn xóa byte 30H phải viết MOV 30H,#00H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Hàm logic bằng bộ xử lý bit","code":"; Ví dụ 6: hàm logic bằng bộ xử lý bit\n; LED P1.2 sáng khi (a AND NOT b) OR c\n; a = bit 00H, b = bit 01H, c = bit 02H (byte 20H)\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     20H,#05H                ; a = 1, b = 0, c = 1\n        MOV     C,00H                   ; C = a\n        ANL     C,/01H                  ; C = a AND (NOT b)\n        ORL     C,02H                   ; C = C OR c\n        CPL     C                       ; LED tích cực mức thấp\n        MOV     P1.2,C                  ; xuất ra chân P1.2\n        SJMP    $\n        END\n","note":"20H = 05H nghĩa là a = 1, b = 0, c = 1. C = a, rồi C = a AND (NOT b) = 1, rồi C OR c = 1. LED tích cực mức thấp nên CPL C trước khi ghi: P1.2 = 0, LED P1.2 sáng. Sửa 20H thành 02H (chỉ b = 1) rồi chạy lại: LED tắt.","dev":{"led":true},"fosc":12000000}];
const sim13=makeSim51(document.getElementById("m51-l13"),{id:"s13",presets:PR13,ram:256});
makeEx51(document.getElementById("ex-l13"),"l13",[{"t":"Bật, tắt từng bit mà không phá byte","d":"<p>Byte <code>20H<\/code> và <code>21H<\/code> chứa các cờ trạng thái của chương trình (vùng bit). Viết chương trình: (1) làm cho LED ở P1.0 và P1.4 sáng, các LED khác tắt (LED sáng khi chân = 0, giả định nối dây của trình mô phỏng); (2) đặt bit <code>05H<\/code> lên 1; (3) xóa bit <code>0FH<\/code> về 0. Mọi bit khác của byte <code>20H<\/code>, <code>21H<\/code> phải giữ nguyên giá trị có sẵn. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>20H = 00H, 21H = 00H<\/code> → <code>20H = 20H, 21H = 00H, P1 = EEH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     P1,#0EEH                ; LED P1.0 và P1.4 sáng\n        MOV     20H,#20H                ; bật bit 05H?\n        MOV     21H,#00H                ; xóa bit 0FH?\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x20":0,"0x21":0}},"expect":{"iram":{"0x20":32,"0x21":0},"ports":{"P1":238}}},{"setup":{"iram":{"0x20":255,"0x21":255}},"expect":{"iram":{"0x20":255,"0x21":127},"ports":{"P1":238}}},{"setup":{"iram":{"0x20":223,"0x21":128}},"expect":{"iram":{"0x20":255,"0x21":0},"ports":{"P1":238}}},{"setup":{"iram":{"0x20":90,"0x21":165}},"expect":{"iram":{"0x20":122,"0x21":37},"ports":{"P1":238}}},{"setup":{"iram":{"0x20":32,"0x21":127}},"expect":{"iram":{"0x20":32,"0x21":127},"ports":{"P1":238}}},{"setup":{"iram":{"0x20":1,"0x21":240}},"expect":{"iram":{"0x20":33,"0x21":112},"ports":{"P1":238}}}]},"hints":["Bit 05H nằm trong byte nào? Vùng bit bắt đầu ở byte 20H, mỗi byte 8 bit: bit 00H–07H thuộc 20H, bit 08H–0FH thuộc 21H.","Ghi cả byte (MOV 20H,#20H) sẽ xóa các bit khác. Lệnh SETB và CLR với địa chỉ bit chỉ đổi đúng một bit.","Mỗi yêu cầu ứng với đúng một lệnh bit; không cần lệnh byte nào."],"why":"Bit 05H là bit 5 của byte 20H, bit 0FH là bit 7 của byte 21H. Code mẫu ghi cả byte nên xóa mất các cờ khác (bộ thử 2, 4, 6). SETB/CLR trên địa chỉ bit đọc–sửa–ghi đúng một bit, mỗi lệnh 2 byte, 1 chu kỳ máy."},{"t":"Hai LED theo hàm logic của ba cờ","d":"<p>Ba cờ nằm trong vùng bit: <i>a<\/i> = bit <code>00H<\/code>, <i>b<\/i> = bit <code>01H<\/code>, <i>c<\/i> = bit <code>02H<\/code>. Viết chương trình cho LED ở P1.0 <b>sáng<\/b> khi <i>a<\/i> AND <i>b<\/i>, LED ở P1.7 <b>sáng<\/b> khi <i>c<\/i> OR (NOT <i>a<\/i>); các chân khác của P1 giữ mức 1. LED sáng khi chân = 0. Byte <code>20H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>20H = 03H<\/code> (a = b = 1, c = 0) → <code>P1 = FEH<\/code>.<\/p>","start":"; a = bit 00H, b = bit 01H, c = bit 02H\n        ORG     0000H\n        MOV     C,00H                   ; C = a\n        ANL     C,01H                   ; C = a AND b\n        MOV     P1.0,C                  ; LED P1.0 (đúng chưa?)\n; LED P1.7: c OR (NOT a) - chưa viết\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x20":3}},"expect":{"iram":{"0x20":3},"ports":{"P1":254}}},{"setup":{"iram":{"0x20":0}},"expect":{"iram":{"0x20":0},"ports":{"P1":127}}},{"setup":{"iram":{"0x20":249}},"expect":{"iram":{"0x20":249},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":7}},"expect":{"iram":{"0x20":7},"ports":{"P1":126}}},{"setup":{"iram":{"0x20":6}},"expect":{"iram":{"0x20":6},"ports":{"P1":127}}},{"setup":{"iram":{"0x20":1}},"expect":{"iram":{"0x20":1},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":253}},"expect":{"iram":{"0x20":253},"ports":{"P1":127}}},{"setup":{"iram":{"0x20":2}},"expect":{"iram":{"0x20":2},"ports":{"P1":127}}}]},"hints":["Chạy code mẫu với 20H = 03H: LED P1.0 có sáng không? Chân P1.0 đang mang giá trị 1 hay 0?","Biểu thức logic tính trong C đúng, nhưng LED nối tích cực mức thấp: phải đảo C trước khi ghi ra chân.","LED tích cực mức thấp: kết quả trong C phải đảo trước khi ra chân. ANL C và ORL C có dạng dùng bit đảo (/bit)."],"why":"Kết quả logic cho biết LED cần sáng hay không, nhưng LED sáng khi chân = 0, nên phải đảo C (CPL C, 1 byte, 1 chu kỳ) trước khi ghi ra chân. Code mẫu ghi thẳng C nên LED P1.0 ngược, và chưa có phần LED P1.7 (tính c OR (NOT a) bằng MOV C,bit rồi ORL C,/bit). Bộ thử 3 và 7 đặt sẵn các bit 3–7 của 20H để bắt cách làm theo cả byte."},{"t":"Xoay vòng ba byte ≤ 6 chu kỳ","d":"<p>Code mẫu xoay vòng ba ô nhớ: ô <code>31H<\/code> nhận giá trị cũ của <code>30H<\/code>, <code>32H<\/code> nhận giá trị cũ của <code>31H<\/code>, <code>30H<\/code> nhận giá trị cũ của <code>32H<\/code>. Code đúng nhưng tốn 10 chu kỳ máy và 14 byte (tính cả <code>SJMP $<\/code>). Hãy viết lại để: toàn chương trình chạy không quá <b>6 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>10 byte<\/b>; R0–R7 của băng 0 (ô <code>00H<\/code>–<code>07H<\/code>) và ô <code>33H<\/code> giữ nguyên. A, B và cờ dùng tự do.<\/p><p>Ví dụ: <code>30H..32H = 11H 22H 33H<\/code> → <code>30H..32H = 33H 11H 22H<\/code>.<\/p>","start":"; Xoay vòng: 31H <- 30H, 32H <- 31H, 30H <- 32H\n; Chạy đúng nhưng chậm và dài. Cần <= 6 chu kỳ, <= 10 byte.\n        ORG     0000H\n        MOV     B,32H                   ; cất 32H cũ vào B\n        MOV     32H,31H\n        MOV     31H,30H\n        MOV     30H,B\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":17,"0x31":34,"0x32":51,"0x33":153}},"expect":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":51,"0x31":17,"0x32":34,"0x33":153}}},{"setup":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":0,"0x31":0,"0x32":0,"0x33":153}},"expect":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":0,"0x31":0,"0x32":0,"0x33":153}}},{"setup":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":255,"0x31":0,"0x32":128,"0x33":153}},"expect":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":128,"0x31":255,"0x32":0,"0x33":153}}},{"setup":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":165,"0x31":165,"0x32":90,"0x33":153}},"expect":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":90,"0x31":165,"0x32":165,"0x33":153}}},{"setup":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":1,"0x31":2,"0x32":3,"0x33":153}},"expect":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":3,"0x31":1,"0x32":2,"0x33":153}}},{"setup":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":195,"0x31":60,"0x32":255,"0x33":153}},"expect":{"iram":{"0x00":15,"0x01":30,"0x02":45,"0x03":60,"0x04":75,"0x05":90,"0x06":105,"0x07":120,"0x30":255,"0x31":195,"0x32":60,"0x33":153}}}],"maxCyc":6,"maxBytes":10},"hints":["Đếm chu kỳ của code mẫu: MOV giữa hai địa chỉ trực tiếp (MOV direct,direct) tốn 3 byte, 2 chu kỳ. Lệnh nào với A chỉ tốn 1 chu kỳ?","XCH A,direct đổi chỗ A với một ô trong 1 chu kỳ, 2 byte: một lệnh vừa ghi giá trị mới vào ô, vừa lấy giá trị cũ ra A.","Sau mỗi lần XCH, A giữ giá trị cũ của ô vừa đổi. Sau hai lần XCH, A đang giữ giá trị nào và còn ô nào chưa được ghi?"],"why":"Mỗi MOV giữa hai địa chỉ trực tiếp tốn 2 chu kỳ, 3 byte. Dùng A làm trung gian: một lệnh đọc 30H vào A, hai lệnh XCH lần lượt với 31H và 32H (mỗi lệnh ghi giá trị mới vào ô và lấy giá trị cũ ra A), một lệnh ghi A vào 30H — 4 lệnh × 1 chu kỳ × 2 byte, cộng SJMP $: 6 chu kỳ, 10 byte. Dùng R7 làm chỗ cất tạm sẽ hỏng bộ thử vì ô 07H phải giữ nguyên."}]);

makeQuiz("quiz13","score13",[{"q": "Ô 30H và ô 26H đều đang bằng FFH. Lệnh CLR 30H làm gì?", "o": ["Xóa bit 30H, tức bit 0 của byte 26H: ô 26H = FEH, ô 30H giữ FFH", "Xóa cả byte 30H về 00H", "Xóa bit 0 của byte 30H: ô 30H = FEH", "Trình dịch báo lỗi vì CLR chỉ nhận A hoặc C"], "a": 0, "e": "CLR với một địa chỉ là lệnh bit (mã C2). Bit 30H nằm trong vùng bit: byte 20H + 30H/8 = 26H, vị trí 0. Byte 30H không bị đụng tới."}, {"q": "Trình dịch kiểu Keil A51 dịch MOV 32H,31H (chép ô 31H sang ô 32H) thành dãy byte nào?", "o": ["85 31 32", "85 32 31", "E5 31 F5 32", "75 32 31"], "a": 0, "e": "Mã 85 là MOV trực tiếp,trực tiếp; trong mã máy byte nguồn (31H) đứng trước byte đích (32H), ngược với thứ tự viết. 75 32 31 là MOV 32H,#31H (ghi số 31H). E5 31 F5 32 là hai lệnh qua A, cùng tác dụng nhưng sửa A."}, {"q": "Lệnh nào KHÔNG có trong tập lệnh 8051?", "o": ["CLR A", "CPL C", "MOV C,ACC.7", "SETB A"], "a": 3, "e": "SETB chỉ nhận C hoặc một địa chỉ bit. CLR A (E4) và CPL A (F4) là lệnh byte có sẵn; MOV C,ACC.7 lấy bit 7 của A vì ACC là SFR có bit đánh địa chỉ được."}, {"q": "Cần đổi đúng một chân P1.0 về 0, giữ nguyên 7 chân còn lại. Cách nào ít byte và ít chu kỳ nhất?", "o": ["ANL P1,#0FEH — 3 byte, 2 chu kỳ", "MOV P1,#0FEH — 3 byte, 2 chu kỳ", "CLR P1.0 — 2 byte, 1 chu kỳ", "CLR C rồi MOV P1.0,C — 3 byte, 3 chu kỳ"], "a": 2, "e": "CLR bit là lệnh đọc–sửa–ghi một bit: 2 byte, 1 chu kỳ. ANL P1,#0FEH đúng nhưng dài hơn. MOV P1,#0FEH ghi cả byte nên phá 7 chân còn lại nếu chúng không bằng 1."}, {"q": "Ô 20H = 06H. Sau MOV C,00H rồi ORL C,/01H, giá trị C bằng bao nhiêu?", "o": ["1", "0", "Không đổi so với trước lệnh MOV", "Trình dịch báo lỗi vì không có ORL C,/bit"], "a": 1, "e": "20H = 0000 0110B nên bit 00H = 0, bit 01H = 1. C = 0, rồi C = 0 OR (NOT 1) = 0. ORL C,/bit có thật (mã A0, 2 byte, 2 chu kỳ); bit 01H không bị đảo."}]);

